import{createLogger}from"#internal/logging.js";import{sleep}from"#public/channels/discord/gateway/connection.js";const log=createLogger(`discord.gateway`),UNSENT_ERROR_CODES=new Set([`ECONNREFUSED`,`ENOTFOUND`,`EAI_AGAIN`,`UND_ERR_CONNECT_TIMEOUT`]);function createForwarder(e){let t=Promise.resolve(),n=0;return{enqueue(e){n>=500?log.error(`Discord Gateway backlog is full; dropped a dispatch`,{event:e.t,sequence:e.s}):(n+=1,t=t.then(()=>deliver(e)).finally(()=>{--n}))},async drain(e){if(n>0){let n=new AbortController;await Promise.race([t,sleep(e,n.signal)]),n.abort()}n>0&&log.warn(`Discord Gateway relay stopped with undelivered dispatches`,{pending:n})}};async function deliver(t){let n=JSON.stringify(t),r={event:t.t,sequence:t.s};for(let t=1;t<=5;t+=1){try{let i=await fetch(e.url,{body:n,headers:{"content-type":`application/json`,...await e.headers()},method:`POST`,signal:AbortSignal.timeout(3e4)});if(i.ok)return;let a=(await i.text()).slice(0,200);if(i.status>=500){log.error(`Gave up forwarding a Discord dispatch that eve may have received`,{...r,detail:a,status:i.status});return}if(i.status!==429){log.error(`eve rejected a forwarded Discord dispatch`,{...r,detail:a,hint:i.status===401||i.status===403?`eve did not accept the relay's credentials. On Vercel, check that the relay runs in the same project as the agent.`:`Check that ${e.url.href} is the agent's discordChannel({ gateway }) route.`,status:i.status});return}log.warn(`Retrying a forwarded Discord dispatch`,{...r,attempt:t,detail:a,status:i.status})}catch(e){if(!UNSENT_ERROR_CODES.has(errorCode(e))){log.error(`Gave up forwarding a Discord dispatch that eve may have received`,{...r,error:e});return}log.warn(`Retrying a forwarded Discord dispatch`,{...r,attempt:t,error:e})}t<5&&await sleep(Math.min(3e4,1e3*2**(t-1)))}log.error(`Gave up forwarding a Discord dispatch`,{...r,attempts:5})}}function errorCode(e){let t=(e instanceof Error?e.cause:void 0)?.code;return typeof t==`string`?t:``}export{createForwarder};